// Compact, interactive explanations. Drawing sizes are illustrative; values are calculated.
const number=v=>Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:2}):'—';
export function wellPartsSketch(w,g){
 const raw=[g.neckHeight,w.slab,g.workingHeight,w.base].map(v=>Math.max(0,v)),scale=128/Math.max(.1,raw.reduce((a,b)=>a+b,0)),heights=raw.map(v=>Math.max(9,v*scale)),total=heights.reduce((a,b)=>a+b,0),factor=138/total;let y=20;
 const items=[['neck','Горловина',g.neckHeight,62,'#bfd9e9'],['slab','Верхняя плита',w.slab,98,'#7d96a8'],['work','Рабочая часть',g.workingHeight,98,'#e7eef3'],['base','Днище',w.base,118,'#7d96a8']];
 const rows=[31,66,113,155],parts=items.map(([id,label,value,width,color],i)=>{const h=heights[i]*factor,x=100-width/2,mid=y+h/2,row=rows[i],html=`<g class="well-part" data-action="focus-parameter" data-param="${id}" data-dimension="${id}" role="button" tabindex="0" aria-label="${label}: ${number(value)} м, изменить"><rect x="${x}" y="${y}" width="${width}" height="${h}" fill="${color}" stroke="#648197"/><path d="M${x+width} ${mid}H169L181 ${row}" fill="none" stroke="#9eb4c4"/><text x="187" y="${row+4}" fill="#36546a" font-size="12">${label}</text><text x="352" y="${row+4}" text-anchor="end" fill="#36546a" font-size="13" font-weight="650">${number(value)} м</text><title>${label}: ${number(value)} м. Нажмите, чтобы изменить.</title></g>`;y+=h;return html}).join('');
 return `<svg viewBox="0 0 365 185" aria-label="Колодец в разрезе, общая высота ${number(g.height)} м"><g class="well-part" data-action="focus-parameter" data-param="height" data-dimension="height" role="button" tabindex="0" aria-label="Общая высота ${number(g.height)} м, изменить"><path d="M35 20H24V158H35M20 20H28M20 158H28" fill="none" stroke="#c96a2d" stroke-width="1.5"/><text x="15" y="90" text-anchor="middle" transform="rotate(-90 15 90)" fill="#b75c25" font-size="12" font-weight="650">Общая ${number(g.height)} м</text></g><path d="M42 18H156" stroke="#97a99a" stroke-dasharray="4 3"/>${parts}</svg>`;
}
export function wellPitSketch(w,g){const sx=260/Math.max(.1,g.topW),sz=115/Math.max(.1,g.depth),bottom=132,top=17,bw=g.width*sx/2,tw=g.topW*sx/2,body=g.bodyW*sx/2,base=g.baseW*sx/2,wellBottom=bottom-w.pad*sz,wellTop=wellBottom-g.height*sz;return `<svg viewBox="0 0 320 165" aria-label="Котлован: зазор для работ и откосы стенок"><path d="M${160-tw} ${top}L${160-bw} ${bottom}H${160+bw}L${160+tw} ${top}" fill="#eef5fa" stroke="#7da1bc" stroke-width="2"/><rect x="${160-body}" y="${wellTop}" width="${2*body}" height="${g.height*sz}" fill="#fff" stroke="#607e93" stroke-width="2"/><rect x="${160-base}" y="${wellBottom}" width="${2*base}" height="${w.pad*sz}" fill="#dbc28d"/><path d="M${160-bw} ${bottom-7}H${160-base}" stroke="#dd6a25" stroke-width="2"/><text x="160" y="75" text-anchor="middle" fill="#43617a" font-size="12">Колодец</text><text x="160" y="155" text-anchor="middle" fill="#c25c22" font-size="12">Зазор для работ: ${number(w.pitMargin)} м с каждой стороны</text></svg>`}
export function rotationSketch(angle){return `<svg viewBox="0 0 320 140" aria-label="Поворот прямоугольного колодца на плане"><path d="M25 112H295M285 107L295 112L285 117" fill="none" stroke="#b8c8d3"/><text x="286" y="132" font-size="12" fill="#637e92">X</text><g transform="rotate(${-angle} 130 67)"><rect x="92" y="29" width="76" height="76" fill="#eaf2f7" stroke="#526f84" stroke-width="2"/><path d="M168 67H235" stroke="#f46a25" stroke-width="5"/><path d="M168 60H175V67" fill="none" stroke="#526f84"/></g><text x="227" y="25" fill="#36546a" font-size="13">${number(angle)}°</text></svg>`}

const hit=(param,label,body)=>`<g class="sketch-control" data-action="focus-parameter" data-param="${param}" data-dimension="${param}" role="button" tabindex="0" aria-label="${label}">${body}<title>${label}. Нажмите для настройки.</title></g>`;
export function pipeParametersSketch(e,res){
 if(!Number.isFinite(res.length)||res.length<=0||!res.points?.length)return '<svg viewBox="0 0 340 180"><text x="20" y="80">Задайте ненулевую длину трубы.</text></svg>';
 const a=res.points[0],b=res.points.at(-1),levels=res.points.map(v=>v.invert),lo=Math.min(...levels),hi=Math.max(...levels),Y=z=>Math.abs(hi-lo)<1e-7?74:54+(hi-z)/(hi-lo)*38,P=v=>[32+v.s/res.length*276,Y(v.invert)],route=res.points.map(v=>P(v).join(',')).join(' '),start=P(a),end=P(b);
 if(!Number.isFinite(res.length)||!res.points.every(v=>Number.isFinite(v.invert)))return '<svg viewBox="0 0 340 180"><text x="20" y="80" fill="#60798c">Укажите отметки низа трубы.</text></svg>';
 return `<svg viewBox="0 0 340 180" aria-label="Длина, диаметр и отметки трубы">${hit('pipe-length','Длина трубы '+number(res.actualLength)+' м',`<path d="M32 28H308M32 22V34M308 22V34" stroke="#63869f" fill="none"/><text x="170" y="18" text-anchor="middle" fill="#36546a" font-size="13">Длина ${number(res.actualLength)} м</text>`)}<polyline points="${route}" fill="none" stroke="#f46a25" stroke-width="${Math.min(18,Math.max(4,e.diameter*20))}" stroke-linejoin="round"/>${hit('pipe-from','Отметка наружного низа в начале '+number(a.invert)+' м',`<circle cx="${start[0]}" cy="${start[1]}" r="7" fill="#fff" stroke="#527791" stroke-width="2"/><text x="15" y="115" fill="#36546a" font-size="12">Начало ${number(a.invert)} м</text>`)}${hit('pipe-to','Отметка наружного низа в конце '+number(b.invert)+' м',`<circle cx="${end[0]}" cy="${end[1]}" r="7" fill="#fff" stroke="#527791" stroke-width="2"/><text x="325" y="115" text-anchor="end" fill="#36546a" font-size="12">Конец ${number(b.invert)} м</text>`)}${hit('pipe-diameter','Диаметр '+number(e.diameter*1000)+' мм',`<circle cx="55" cy="150" r="${Math.min(23,Math.max(8,e.diameter*40))}" fill="#f46a25" stroke="#527791" stroke-width="2"/><path d="M38 150H72" stroke="white"/><text x="85" y="154" fill="#36546a" font-size="13">Ø ${number(e.diameter*1000)} мм</text>`)}<text x="225" y="156" text-anchor="middle" fill="#6a8395" font-size="12">Уклон ${number((res.portA.invert-res.portB.invert)/res.length*1000)} ‰</text></svg>`;
}
export function trenchParametersSketch(e,s,c){
 if(s.method!=='trench')return '<svg viewBox="0 0 340 200"><text x="30" y="100" fill="#60798c">Труба на опорах — траншеи нет.</text></svg>';
 if(![c.width,c.top,c.depth,c.left,c.right].every(Number.isFinite)||c.width<=0||c.top<=0||c.depth<=0)return '<svg viewBox="0 0 340 200"><text x="15" y="95" fill="#60798c">Сначала исправьте глубину и размеры.</text></svg>';

 const left=c.width/2+c.left*c.depth,right=c.width/2+c.right*c.depth,scale=250/(left+right),X=x=>40+(x+left)*scale,top=38,bottom=150,sz=(bottom-top)/c.depth,xl=X(-c.width/2),xr=X(c.width/2),axis=bottom-(c.axis-c.bottom)*sz,r=Math.min(e.diameter/2*scale,e.diameter/2*sz),bed=bottom-s.bedding*sz,angle=v=>Math.atan2(1,v)*180/Math.PI;
 return `<div class="sketch-caption">Сечение на ${number(c.s)} м от начала</div><svg viewBox="0 0 340 200" aria-label="Поперечное сечение траншеи на ${number(c.s)} м"><path d="M40 ${top}L${xl} ${bottom}H${xr}L290 ${top}" fill="#e7dcc4" stroke="#809cae" stroke-width="1.5"/><path d="M${xl} ${bottom}H${xr}L${X(c.width/2+c.right*s.bedding)} ${bed}H${X(-c.width/2-c.left*s.bedding)}Z" fill="#d9b56f"/>${s.casing?`<circle cx="${X(0)}" cy="${axis}" r="${Math.max(3,c.radius*Math.min(scale,sz))}" fill="#c8d3dc" stroke="#527791"/>`:""}<circle cx="${X(0)}" cy="${axis}" r="${Math.max(3,r)}" fill="#f46a25" stroke="#527791"/>${hit('trench-top','Ширина поверху '+number(c.top)+' м',`<path d="M40 25H290M40 20V30M290 20V30" stroke="#63869f"/><text x="165" y="16" text-anchor="middle" fill="#36546a" font-size="13">Поверху ${number(c.top)} м</text>`)}${hit('trench-width','Ширина дна '+number(c.width)+' м',`<path d="M${xl} 165H${xr}M${xl} 160V170M${xr} 160V170" stroke="#63869f"/><text x="165" y="187" text-anchor="middle" fill="#36546a" font-size="13">Дно ${number(c.width)} м</text>`)}${hit('trench-depth','Глубина '+number(c.depth)+' м; меняется отметками трубы и подушкой',`<path d="M305 ${top}H312V${bottom}H305" fill="none" stroke="#63869f"/><text x="328" y="95" transform="rotate(-90 328 95)" text-anchor="middle" fill="#36546a" font-size="12">Глубина ${number(c.depth)} м</text>`)}${hit('trench-left','Левый откос '+number(angle(c.left))+' градусов',`<text x="${Math.max(24,(40+xl)/2)}" y="96" text-anchor="middle" fill="#a15e2d" font-size="12">${number(angle(c.left))}°</text>`)}${hit('trench-right','Правый откос '+number(angle(c.right))+' градусов',`<text x="${Math.min(294,(290+xr)/2)}" y="96" text-anchor="middle" fill="#a15e2d" font-size="12">${number(angle(c.right))}°</text>`)}</svg>`;
}
